"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["5288"],{5825(e,t,n){n.r(t),n.d(t,{metadata:()=>r,default:()=>h,frontMatter:()=>a,contentTitle:()=>s,toc:()=>c,assets:()=>l});var r=JSON.parse('{"id":"reference/register/howtos/registerECCSIMToDevice","title":"How to merge ECC SIM cards with an AirLink router at Registration","description":"avc \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/register/howtos/registerECCSIMToDevice.md","sourceDirName":"reference/register/howtos","slug":"/reference/register/howtos/registerECCSIMToDevice","permalink":"/personal-av-docs/docs/reference/register/howtos/registerECCSIMToDevice","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/register/howtos/registerECCSIMToDevice.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to merge ECC SIM cards with an AirLink router at Registration","sidebar_label":"How to merge ECC SIM cards with an AirLi","sidebar_position":99,"edition":"avc","source":"https://doc.airvantage.net/avc/reference/register/howtos/registerECCSIMToDevice","format":"md"}}'),o=n(4848),i=n(8453);let a={title:"How to merge ECC SIM cards with an AirLink router at Registration",sidebar_label:"How to merge ECC SIM cards with an AirLi",sidebar_position:99,edition:"avc",source:"https://doc.airvantage.net/avc/reference/register/howtos/registerECCSIMToDevice",format:"md"},s,l={},c=[];function u(e){let t={a:"a",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsxs)(t.p,{children:[":::note Edition\n",(0,o.jsx)(t.strong,{children:"avc"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,o.jsx)(t.a,{href:"https://doc.airvantage.net/avc/reference/register/howtos/registerECCSIMToDevice",children:"Original page"}),".\n:::"]}),"\n",(0,o.jsx)(t.p,{children:'How to merge ECC SIM cards with an AirLink router at Registration\nHow to register AirPrime modules into your AirVantage account\nHow to retrieve device data in a dataset?\nHow to set up IMEI lock?\nHow to set up your system?\nHow to find a system\nAPI & Connectors\nGetting Started with the AirVantage API\nAPI Libraries & Examples\nGetting started with the Cloud Connectors\nReferences\nDevice Communication\nDevice Protocols\nApplication Format Reference\nUser Interface\nActivities\nData Visualization\nAccount Administration\nAPI & Connectors\nWeb Services API\nCloud Connectors\nCloud Connectors Format\nUSSD Gateway\nMore\nProduct Page\nFAQ\nGDPR FAQ\nSearching...\nMatching results\nHow to merge ECC SIM cards with an AirLink router at Registration\nYou can merge your AirLink router with an Enhanced Carrier Connectivity (ECC) SIM during registration, creating a single System from the two components and activating the system on a bundle offer (AirLink Complete and ECC Connectivity).\nThis process simplifies the management of your ALMS account, reducing the overall number of Systems, managing the System lifecycle as a whole, and providing a consolidated view of your routers and the SIMs they contain.\nThese registration procedures show you how to select the SIM card that you have installed into the router and pick the right connectivity bundle offer to activate. ALMS merges the two entities into a single System combining the router and the ECC SIM.\nPre-requisites\nYou must have ECC SIMs in your account in the\nInventory\nstate. You can purchase ECC SIMs from your AirVantage account and have them shipped to you. For more information on ordering SIMs, please refer to\nHow to order new SIMs?\n. When your ECC SIM order is processed, each SIM\u2019s ID number is added to your AirVantage account as a separate System. New SIMs are automatically put in the\nInventory\nstate until you activate them.\nPreparing your devices\nBefore registering your routers in ALMS:\nInsert your ECC SIMs into your routers.\nDocument the router serial numbers with their associated SIM IDs. It is important to ensure you have the correct association of the router and the SIM for the next step of the process.\nEnsure your routers can acquire an APN and get on air. Unless you are on a private network, the router should acquire the APN automatically. Otherwise, you may need to manually configure the APN in ACEmanager or apply a template containing the APN to multiple devices. Please refer to the documentation with your SIMs to validate the APN that will be used.\nNote: If you select the wrong SIM during the Registration process, and it does not match the SIM in the router, the process will fail, and you will receive an error message.\nMerge an ECC SIM with an AirLink router using Register\nYou can merge your AirLink router with an ECC SIM using the AirVantage Register page (best for a single router and ECC SIM). Alternatively, to register a large number of devices you can bulk import their details in a CSV file containing lists of devices, ECC SIMs and offers. See below for complete details.\nDisplay the Register page\nClick the Register widget on the Start page, or the\nRegister\ntab from the top menu bar.\nEnter the router details\nEnter the serial number. AirVantage identifies the device type.\nIf AirVantage does not identify your system type (or misidentifies your system type) when you enter the serial number, click\nSelect system type\nin the top left corner. The device catalog appears, and you can select your system type from there.\nEnter your second identifying factor for your device.\nIf your device runs ALEOS, enter the IMEI\nIf your device runs AirLink OS, enter the Registration Code\nBoth pieces of information can be found on the device label\n(Optional) Enter a unique Name for the system.\nSelect the ECC SIM installed in the router from the list. The list shows only ECC SIMs that are in the\nInventory\nstate.\nNote:\nThe\nSIM\nentry on the Register screen appears only if there are ECC SIMs in the\nInventory\nstate in your AirVantage account.\nSelect the ECC offer to activate for that SIM. Ensure that you select the offer that applies to the ECC SIMs you have purchased.\nClick\nRegister\n.\nBulk registration using a CSV file\nFor general information about using CSV files to register devices, see\nHow to register a list of systems?\nOn the registration details page, click\nImport a list\n. An\nImport Systems\ndialog box opens.\nDownload the CSV import file template by clicking\nDownload template\n.\nBuild a\nCSV file\nthe details for the router. See\nHow to register a list of systems?\nfor more information on creating a CSV for bulk import. In order for the gateway or router and SIM to be merged, there must be two corresponding pieces of information for the two components:\nThe\nICCID\nof the\nECC SIM\nin the\nSUBSCRIPTION[IDENTIFIER]\ncolumn.\nThe\nSerial Number\nof the\ngateway\nor\nrouter\nin the\nGATEWAY[SERIAL NUMBER]\ncolumn.\nClick\nSelect a CSV\nand select your CSV file. The\nImport Systems\nwindow warns you if any entries in your CSV are missing or incomplete.\nSelect an offer. Ensure that you select the offer that applies to the ECC SIMs you have purchased.\nThe offers list will only show ECC offers; however it will not sort the list of available offers according to your ECC SIM inventory. It will not filter out carriers, for example. Bulk import only looks at the\nSubscription [Identifier]\ncolumn. If the header has no data below it, the Import Systems dialog will display an error.\nClick\nImport\n.\nAll devices in your\nCSV file\nmust be routers of the\nsame type\n(e.g. MP70). If you have\nmultiple device types to register\n, please build\none CSV file per type\n.\nIn addition, all ECC SIMs in your\nCSV file\nmust be of the\nsame carrier\n, as they will all be activated on the same offer. For example, if you have 50 AirLink MP70 routers on a 1 GB plan, and you have 25 MP70 routers on a 10 GB plan, you must upload separate CSV files for each offer.\nSimilarly, if you have 50 SIMs (25 for AT&T and 25 for TMobile) installed in your routers, you must upload separate CSV files for each.\nBelow is a valid CSV format, with 3 devices, that you may use as a reference:\n"SUBSCRIPTION[IDENTIFIER]","GATEWAY[SERIAL NUMBER]"\n89332500000000654321,V9876540123456\n89332500000000654322,V9876540123457\n89332500000000654323,V9876540123458\nYour CSV file should include a header line as above, plus one line per system you wish to register.\nIf the CSV file is partially filled - for example, a subscription ID is missing for a router in the CSV - an error message appears after you import the file. Every router in the CSV must be linked to an ECC SIM. If you want to register non-ECC routers, you must upload a separate CSV file.'})]})}function h(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(u,{...e})}):u(e)}},8453(e,t,n){n.d(t,{R:()=>a,x:()=>s});var r=n(6540);let o={},i=r.createContext(o);function a(e){let t=r.useContext(i);return r.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),r.createElement(i.Provider,{value:t},e.children)}}}]);